    "html": "<div style=\"padding:16px\"><div style=\"font-size:16px;font-weight:700;color:var(--phone-text-1);letter-spacing:-.02em;line-height:1.2\">Выберите карту в кошельке</div><div style=\"font-size:11px;color:var(--phone-text-2);margin-top:4px\">Или выпустите новую</div><div style=\"margin-top:12px\"><div style=\"background:var(--phone-surf);border:1.5px solid var(--ink-1);border-radius:11px;padding:10px 12px;margin-bottom:8px;display:flex;align-items:center;gap:10px\"><div style=\"width:34px;height:24px;background:var(--ink-1);border-radius:4px;display:flex;align-items:center;justify-content:center\"><div style=\"width:9px;height:9px;border-radius:2px;background:var(--bk)\"></div></div><div style=\"flex:1\"><div style=\"font-size:12px;font-weight:600;color:var(--phone-text-1)\">Карта Альфа-Банка</div><div class=\"num\" style=\"font-size:10px;color:var(--phone-text-2)\">····4567 · 15 200 ₽</div></div><span style=\"width:16px;height:16px;border-radius:50%;border:1.5px solid var(--ink-1);display:flex;align-items:center;justify-content:center\"><span style=\"width:8px;height:8px;border-radius:50%;background:var(--ink-1)\"></span></span></div><div style=\"background:#fff;border:1px solid var(--phone-line-1);border-radius:11px;padding:10px 12px;margin-bottom:8px;display:flex;align-items:center;gap:10px\"><div style=\"width:34px;height:24px;background:var(--ink-1);border-radius:4px;display:flex;align-items:center;justify-content:center\"><div style=\"width:9px;height:9px;border-radius:2px;background:var(--bk)\"></div></div><div style=\"flex:1\"><div style=\"font-size:12px;font-weight:600;color:var(--phone-text-1)\">Карта Альфа-Банка</div><div class=\"num\" style=\"font-size:10px;color:var(--phone-text-2)\">····3456 · 1 100 ₽</div></div><span style=\"width:16px;height:16px;border-radius:50%;border:1.5px solid var(--phone-line-1);display:flex;align-items:center;justify-content:center\"></span></div><div style=\"display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:11px;border:1px dashed var(--line-3)\"><div style=\"width:34px;height:24px;border-radius:4px;border:1px dashed var(--line-3);display:flex;align-items:center;justify-content:center;font-size:16px;color:var(--phone-text-2);font-weight:300\">+</div><span style=\"flex:1;font-size:12px;font-weight:600;color:var(--phone-text-1)\">Выпустить новую карту</span></div></div><div style=\"margin-top:12px\"><button style=\"background:var(--ink-1);color:#fff;border:none;border-radius:11px;padding:12px 0;font-weight:600;font-size:13px;text-align:center\" type=\"button\" class=\"phone-tap\" data-phone-action=\"К оплате\">К оплате</button></div></div>"
